</div>

<script>
const nf = new Intl.NumberFormat('hu-HU',{maximumFractionDigits:0});
const nf2 = new Intl.NumberFormat('hu-HU',{minimumFractionDigits:2,maximumFractionDigits:2});
const ft = n => nf.format(Math.round(n)) + ' Ft';

function compute(P, annualRate, n){
  const r = annualRate/100/12;
  const payment = r===0 ? P/n : P*(r*Math.pow(1+r,n))/(Math.pow(1+r,n)-1);
  const rows=[]; let bal=P, tP=0,tC=0,tI=0;
  for(let m=1;m<=n;m++){
    const interest=bal*r;
    let principal=payment-interest;
    if(m===n) principal=bal;
    bal=Math.max(0,bal-principal);
    tP+=payment; tC+=principal; tI+=interest;
    rows.push({m,payment,principal,interest,bal});
  }
  return {payment,rows,totalPaid:tP,totalCap:tC,totalInt:tI};
}

function termText(n){
  const y=Math.floor(n/12), m=n%12;
  if(y&&m) return y+' év '+m+' hónap';
  if(y) return y+' év';
  return m+' hónap';
}

function render(data){
  document.getElementById('sMonthly').textContent=ft(data.payment);
  document.getElementById('sTotal').textContent=ft(data.totalPaid);
  document.getElementById('sInterest').textContent=ft(data.totalInt);
  document.getElementById('sTerm').textContent=termText(data.rows.length);
  document.getElementById('fTotal').textContent=ft(data.totalPaid);
  document.getElementById('fCap').textContent=ft(data.totalCap);
  document.getElementById('fInt').textContent=ft(data.totalInt);
  const tb=document.getElementById('tbody'); tb.textContent='';
  const rows=data.rows, n=rows.length;
  for(let y=1;(y-1)*12<n;y++){
    const start=(y-1)*12, end=Math.min(y*12,n);
    let yrP=0,yrC=0,yrI=0;
    for(let i=start;i<end;i++){yrP+=rows[i].payment;yrC+=rows[i].principal;yrI+=rows[i].interest;}
    const tr=document.createElement('tr');
    const cells=[y+'.', yrP, yrC, yrI, rows[end-1].bal];
    cells.forEach((c,i)=>{
      const td=document.createElement('td');
      td.textContent = i===0 ? c : ft(c);
      tr.appendChild(td);
    });
    tb.appendChild(tr);
  }
  document.getElementById('empty').hidden=true;
  document.getElementById('results').hidden=false;
}

function calc(){
  const a=parseFloat(document.getElementById('amount').value);
  const r=parseFloat(document.getElementById('rate').value);
  const n=parseInt(document.getElementById('months').value,10);
  const live=document.getElementById('live');
  if(!(a>0)){live.textContent='Kérlek, adj meg egy pozitív hitelösszeget.';return;}
  if(!(r>=0)){live.textContent='Kérlek, adj meg egy nem negatív évi kamatot.';return;}
  if(!(Number.isFinite(n)&&n>=1)){live.textContent='Kérlek, adj meg egy legalább 1 hónapos futamidőt.';return;}
  render(compute(a,r,n));
  live.textContent='Kiszámolva: havi törlesztő '+ft(compute(a,r,n).payment)+'.';
}

const form=document.getElementById('form');
form.addEventListener('submit',e=>{e.preventDefault();calc();});
document.getElementById('clearBtn').addEventListener('click',()=>{
  document.getElementById('amount').value='';
  document.getElementById('rate').value='';
  document.getElementById('months').value='';
  document.getElementById('results').hidden=true;
  document.getElementById('empty').hidden=false;
  document.getElementById('live').textContent='Mezők törölve.';
});

function save(){
  if(!(window.alfy&&window.alfy.storage))return;
  window.alfy.storage.set('loan-calc',{
    amount:document.getElementById('amount').value,
    rate:document.getElementById('rate').value,
    months:document.getElementById('months').value
  });
}
['amount','rate','months'].forEach(id=>{
  document.getElementById(id).addEventListener('input',save);
});

(async function init(){
  if(window.alfy&&window.alfy.storage){
    try{
      const s=await window.alfy.storage.get('loan-calc');
      if(s){
        document.getElementById('amount').value=s.amount||'';
        document.getElementById('rate').value=s.rate||'';
        document.getElementById('months').value=s.months||'';
        const a=parseFloat(s.amount),r=parseFloat(s.rate),n=parseInt(s.months,10);
        if(a>0&&r>=0&&Number.isFinite(n)&&n>=1) render(compute(a,r,n));
      }
    }catch(e){}
  }
})();
</script>
</body>
</html>
